import{_ as o,o as t,c as a,ag as i}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"科学日报 · 2026-09-13（神经科学）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/neuroscience/science-daily-2026-09-13.md","filePath":"topics/neuroscience/science-daily-2026-09-13.md"}'),l={name:"topics/neuroscience/science-daily-2026-09-13.md"};function c(r,e,n,s,u,d){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="科学日报-·-2026-09-13-神经科学" tabindex="-1">科学日报 · 2026-09-13（神经科学） <a class="header-anchor" href="#科学日报-·-2026-09-13-神经科学" aria-label="Permalink to &quot;科学日报 · 2026-09-13（神经科学）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-13.md</code> — 第24期</p></blockquote><hr><h2 id="wholistic-对全身器官细胞活动进行活体成像-nature" tabindex="-1">WHOLISTIC：对全身器官细胞活动进行活体成像（Nature） <a class="header-anchor" href="#wholistic-对全身器官细胞活动进行活体成像-nature" aria-label="Permalink to &quot;WHOLISTIC：对全身器官细胞活动进行活体成像（Nature）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-13.md</code> ｜ DOI: 10.1038/s41586-026-10979-6</p></blockquote><ul><li>生理学长期受限于&quot;无法同时记录全身范围内变化的细胞活动&quot;。WHOLISTIC（Whole-Organism Live-Imaging System for recording Tissue and IntraCellular activity）在<strong>斑马鱼幼鱼全身、细胞分辨率、秒级时间尺度</strong>成像细胞活动，并在成年 Danionella 脑中完成概念验证。</li><li>整合体积荧光显微镜 + 机器学习 + 全细胞转基因钙传感器（GCaMP），并推进全身膨胀显微术衔接分子/超微结构；联合光遗传实现全光学脑-体因果解析。</li><li>多尺度发现：单细胞（软骨细胞对冷刺激、脑膜对氯胺酮的反应）、器官（肾单位沿程的节律性行波）、多器官（未知肌肉协同与肌肉-器官互作）、整个生命体（脑干控制的全身血流再分配）。</li><li>洞察：打通&quot;细胞—器官—机体&quot;的系统级观测，正是本主题&quot;身体作为意识/生理的引擎&quot;（模块三/五）的实证底座——同时记录整个机体，才能谈&quot;全身回路&quot;式的整体因果。</li></ul><h2 id="微胶质细胞经腺苷-a3-受体稳定睡眠稳态-sci-adv" tabindex="-1">微胶质细胞经腺苷 A3 受体稳定睡眠稳态（Sci Adv） <a class="header-anchor" href="#微胶质细胞经腺苷-a3-受体稳定睡眠稳态-sci-adv" aria-label="Permalink to &quot;微胶质细胞经腺苷 A3 受体稳定睡眠稳态（Sci Adv）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-13.md</code> ｜ DOI: 10.1126/sciadv.aef3957</p></blockquote><ul><li>睡眠压力部分由胞外腺苷（eADO）累积调控，但微胶质细胞如何&quot;感知&quot;睡眠压力此前不清。利用自由活动小鼠的<strong>微型双光子显微镜</strong>，发现微胶质钙活动由脑状态转变快速调制，且主要由腺苷 A3 受体（A3R）响应脑状态依赖的 eADO 波动所介导。</li><li>微胶质特异敲除 A3R → 减弱状态依赖钙动态、损害跨睡眠-觉醒周期的形态可塑性、通过增加觉醒↔NREM 切换导致<strong>睡眠碎片化</strong>。</li><li>结论：微胶质细胞经 eADO-A3R 通路&quot;稳定觉醒与 NREM 两者&quot;，从而维持睡眠稳态。</li><li>洞察：免疫细胞（小胶质）直接卷入睡眠调节——既是\\神经免疫&quot;跨层接口的新证据，也贴合&quot;自下而上（胶质/代谢信号）&quot;&quot;调节高阶状态（睡眠）&quot;的主线。</li></ul>',9)])])}const _=o(l,[["render",c]]);export{h as __pageData,_ as default};
